import { mkdir, readdir, rm, writeFile } from 'node:fs/promises';
import { buildPlan, traceScenario, type Workspace } from '@tc/model';
import type { Suite } from './runtime/index.ts';
import { generatedActions } from './actions-loader.ts';

const header = (source: string, revision: string) => `// Generated by Test Cartographer from ${source} (revision ${revision}).
// Do not edit by hand: change the model and recompile (\`tc compile\`).
`;

// A plain object, not defineConfig(): a project needn't have @playwright/test itself.
const config = `// Generated by Test Cartographer.
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));

export default {
  testDir: here,
  outputDir: resolve(here, '../runs/artifacts'),
  fullyParallel: true,
  retries: 0,
  timeout: 60_000,
  use: {
    tcWorkspace: resolve(here, '..'),
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
};
`;

// Compiles the confirmed model into Playwright tests: one spec per entity.
export async function compile(ws: Workspace): Promise<{ files: string[]; scenarios: number }> {
  const dir = ws.path('generated');
  await mkdir(dir, { recursive: true });
  for (const f of await readdir(dir)) if (f.endsWith('.spec.ts')) await rm(ws.path('generated', f));

  const project = await ws.project();
  const catalog = await ws.catalog();
  const { backlog } = await ws.backlog();
  // Story tags use the tracker key when there is one, the story id otherwise.
  const storyKeys = Object.fromEntries(backlog.stories.map((s) => [s.id, s.key ?? s.id]));
  const files: string[] = [];
  let scenarios = 0;
  const generated = generatedActions(ws);
  for (const id of await ws.entityIds()) {
    const { entity, revision } = await ws.entity(id);
    const plan = buildPlan(entity, project, catalog);
    const source = `entities/${id}.yaml`;
    const suite: Suite = {
      title: entity.title,
      source,
      revision,
      entity: { id: entity.id, key: entity.key, reader: entity.reader },
      readers: Object.fromEntries(Object.values(catalog).map((e) => [e.id, e.reader])),
      relations: Object.fromEntries(entity.relations.map((r) => [r.id, { entity: r.entity, field: r.field }])),
      storyKeys,
      // Each scenario's own epic/feature/story labels, for Allure-compatible tags.
      scenarios: plan.scenarios.map((s) => ({ ...s, trace: traceScenario(backlog, entity, s) })),
    };
    const body = [
      header(source, revision),
      `import { defineSuite } from '@tc/engine/runtime';`,
      `import actions from '../actions/index.ts';`,
      ...(Object.keys(generated).length ? [`import { stepsAction } from '@tc/engine/actions';`] : []),
      '',
      `defineSuite(${JSON.stringify(suite, null, 2)}, { ${Object.entries(generated).map(([name, def]) => `${JSON.stringify(name)}: stepsAction(${JSON.stringify(def)}), `).join('')}...actions });`,
      '',
    ].join('\n');
    const file = `generated/${id}.spec.ts`;
    await writeFile(ws.path(file), body);
    files.push(file);
    scenarios += plan.scenarios.length;
  }
  await writeFile(ws.path('generated', 'playwright.config.ts'), config);
  return { files, scenarios };
}
